import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [students, setStudents] = useState([]);
  const [formData, setFormData] = useState({ name: '', studentId: '', major: '', age: '' });

  const fetchStudents = async () => {
    try {
  axios.post('http://localhost:5000/api/students', formData)
      setStudents(response.data);
    } catch (err) {
      console.error('Lỗi khi tải danh sách sinh viên:', err);
    }
  };

  useEffect(() => {
    fetchStudents();
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
 await axios.post('/api/students', formData);
      setFormData({ name: '', studentId: '', major: '', age: '' });
      fetchStudents();
    } catch (err) {
      console.error('Lỗi khi thêm sinh viên:', err);
    }
  };

  const handleDelete = async (id) => {
    try {
      await axios.delete(`/api/students/${id}`);
      fetchStudents();
    } catch (err) {
      console.error('Lỗi khi xóa sinh viên:', err);
    }
  };

  return (
    <div style={{ padding: '20px', fontFamily: 'Arial' }}>
      <h2>Ứng dụng Quản lý Sinh viên (MERN Stack)</h2>

      <form onSubmit={handleSubmit} style={{ marginBottom: '20px' }}>
        <input 
          type="text" placeholder="Họ tên" 
          value={formData.name} onChange={e => setFormData({...formData, name: e.target.value})} required 
        />
        <input 
          type="text" placeholder="Mã SV" 
          value={formData.studentId} onChange={e => setFormData({...formData, studentId: e.target.value})} required 
        />
        <input 
          type="text" placeholder="Chuyên ngành" 
          value={formData.major} onChange={e => setFormData({...formData, major: e.target.value})} required 
        />
        <input 
          type="number" placeholder="Tuổi" 
          value={formData.age} onChange={e => setFormData({...formData, age: e.target.value})} required 
        />
        <button type="submit">Thêm Sinh Viên</button>
      </form>

      <table border="1" cellPadding="10" style={{ borderCollapse: 'collapse', width: '100%' }}>
        <thead>
          <tr>
            <th>Họ tên</th>
            <th>Mã SV</th>
            <th>Chuyên ngành</th>
            <th>Tuổi</th>
            <th>Hành động</th>
          </tr>
        </thead>
        <tbody>
          {students.map(student => (
            <tr key={student._id}>
              <td>{student.name}</td>
              <td>{student.studentId}</td>
              <td>{student.major}</td>
              <td>{student.age}</td>
              <td>
                <button onClick={() => handleDelete(student._id)}>Xóa</button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default App;
